--- index.html
+++ index.html
@@ -70,9 +70,9 @@
  const descriptions=[['Jokes, facts & fun','Songs and showtime','A surprising bit of trivia','Calendar and reminders'],['Start a letter or document','Office know-how','Handy productivity tip','Contextual writing help'],['Find your next step','A guided walkthrough','Friendly task assistance','A sprinkle of magic']];
  const $=id=>document.getElementById(id); let running=false, time=45, score=0, streak=0, mistakes=0, index=0, tick=null, locked=false, sound=false, shuffled=[];
  const options=$('options');
  function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
- function render(){let r=shuffled[index];$('prompt').textContent=r.q;$('requestSub').textContent=r.sub;$('requestCount').textContent=`REQUEST ${String(index+1).padStart(2,'0')} / 12`;$('progress').style.width=`${index/12*100}%`;$('progressText').textContent=`${index} / 12`;$('feedback').textContent='';$('feedback').className='feedback';options.innerHTML='';let correctName=names[r.correct];let choices=[r.correct,...shuffle([0,1,2].filter(x=>x!==r.correct))];choices.forEach((c,n)=>{let b=document.createElement('button');b.type='button';b.className='option';b.dataset.assistant=c;b.innerHTML=`<span class="option-num">${n+1}</span><span class="option-copy"><span class="option-name">${names[c]} · ${actionNames[c][r.correct===c?Math.max(0,actionNames[c].indexOf(r.action)):Math.floor(Math.random()*actionNames[c].length)]}</span><span class="option-desc">${descriptions[c][Math.floor(Math.random()*descriptions[c].length)]}</span></span><span class="option-arrow">↗</span>`;b.addEventListener('click',()=>answer(c,b));options.appendChild(b)});if(!running){$('prompt').textContent='The request queue is ready.';$('requestSub').textContent='Start your shift when you’re ready.';options.innerHTML='';}}
+ function render(){if(!running){$('prompt').textContent='The request queue is ready.';$('requestSub').textContent='Start your shift when you’re ready.';options.innerHTML='';return}let r=shuffled[index];$('prompt').textContent=r.q;$('requestSub').textContent=r.sub;$('requestCount').textContent=`REQUEST ${String(index+1).padStart(2,'0')} / 12`;$('progress').style.width=`${index/12*100}%`;$('progressText').textContent=`${index} / 12`;$('feedback').textContent='';$('feedback').className='feedback';options.innerHTML='';let correctName=names[r.correct];let choices=[r.correct,...shuffle([0,1,2].filter(x=>x!==r.correct))];choices.forEach((c,n)=>{let b=document.createElement('button');b.type='button';b.className='option';b.dataset.assistant=c;b.innerHTML=`<span class="option-num">${n+1}</span><span class="option-copy"><span class="option-name">${names[c]} · ${actionNames[c][r.correct===c?Math.max(0,actionNames[c].indexOf(r.action)):Math.floor(Math.random()*actionNames[c].length)]}</span><span class="option-desc">${descriptions[c][Math.floor(Math.random()*descriptions[c].length)]}</span></span><span class="option-arrow">↗</span>`;b.addEventListener('click',()=>answer(c,b));options.appendChild(b)});if(!running){$('prompt').textContent='The request queue is ready.';$('requestSub').textContent='Start your shift when you’re ready.';options.innerHTML='';}}
  function say(text){$('speech').textContent=text;$('speech').classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>$('speech').classList.remove('show'),2100)}
  function animate(c,good){ids.forEach((id,i)=>$(id).style.display=i===c?'block':'none');$('characterName').textContent=`${names[c].toUpperCase()} · ${good?'ON THE JOB':'OOPS, TRY AGAIN'}`;$('stageCaption').textContent=good?`${names[c].toUpperCase()} IS ON THE JOB`:'THAT ASSISTANT DOESN’T HAVE THIS ONE';$('agentWrap').classList.remove('idle','pop','good');void $('agentWrap').offsetWidth;$('agentWrap').classList.add('pop');if(good)$('agentWrap').classList.add('good');}
  function toast(txt){$('toast').textContent=txt;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),900)}
  function update(){ $('score').textContent=String(score).padStart(3,'0');$('streak').textContent=streak;$('clock').innerHTML=`${time}<small> sec</small>`;$('timerText').textContent=`${time} SEC`;for(let i=1;i<=3;i++)$('life'+i).classList.toggle('on',i>mistakes);}
